/**
 * Which competencies each module section teaches, so a review opens only the
 * relevant sections (2026-10-28).
 *
 * DRAFT: generated by matching each section's title and text against keyword
 * lists per competency (scripts/_tagLessons.ts, not committed). The group
 * checks and corrects these tags; until then a competency with no tagged
 * section in a module falls back to its tagged sections in the stage that
 * introduced it, and then to the whole module.
 */
import type { DrivingCompetency } from '@/domain/learner/competency';
import { introStageOf } from '@/domain/learner/stageCompetencies';
import type { Lesson, LevelModule } from '@/features/driving-sim/domain/scenario/lessonModule';
import { getLevelModule } from './lessonCatalog';
import tags from './lessonCompetencies.json';

const TAGS = tags as Record<string, DrivingCompetency[]>;

export const lessonCompetencies = (lessonId: string): DrivingCompetency[] => TAGS[lessonId] ?? [];

const tagged = (module: LevelModule, competency: DrivingCompetency): Lesson[] =>
  module.lessons.filter(lesson => lessonCompetencies(lesson.id).includes(competency));

/** The sections to review for these competencies at a stage: its own tagged sections, else the intro stage's, else the whole module. */
export const reviewLessons = (level: number, competencies: readonly DrivingCompetency[]): Lesson[] => {
  const module = getLevelModule(level);
  const picked = new Map<string, Lesson>();
  for (const competency of competencies) {
    const own = tagged(module, competency);
    const fromIntro = own.length > 0 ? own : tagged(getLevelModule(introStageOf(competency)), competency);
    for (const lesson of fromIntro) picked.set(lesson.id, lesson);
  }
  return picked.size > 0 ? [...picked.values()] : module.lessons;
};
